<x-filament-panels::page><div wire:poll.10s>@php($s=$this->stats)<style>.br{display:flex;flex-direction:column;gap:18px}.br-hero,.br-panel,.br-stat{border:1px solid rgba(124,58,237,.18);border-radius:18px;background:#fff}.br-hero{padding:22px;background:linear-gradient(125deg,#fff,#f5f3ff,#ede9fe);display:flex;justify-content:space-between;gap:16px}.br-title{font-size:27px;font-weight:950;color:#111827}.br-sub{color:#6b7280;font-size:12px}.br-btn{border:0;border-radius:11px;padding:11px 15px;background:linear-gradient(135deg,#7c3aed,#17111f);color:#fff;font-weight:850}.br-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.br-stat{padding:15px}.br-stat span{font-size:9px;font-weight:900;color:#7c3aed;text-transform:uppercase}.br-stat b{display:block;font-size:20px;color:#111827;margin-top:4px}.br-table{overflow:auto}.br-table table{width:100%;min-width:850px;border-collapse:collapse}.br-table th,.br-table td{padding:12px;border-bottom:1px solid #eee;text-align:left;font-size:10px}.br-action{border:0;padding:6px 9px;border-radius:8px;background:#ede9fe;color:#5b21b6;font-weight:800}.br-note{padding:16px;color:#6b7280;font-size:11px;line-height:1.6}html.dark .br-hero,html.dark .br-panel,html.dark .br-stat{background:linear-gradient(145deg,#09080e,#171023);border-color:rgba(167,139,250,.24)}html.dark .br-title,html.dark .br-stat b,html.dark .br-table td{color:#f8fafc}@media(max-width:900px){.br-stats{grid-template-columns:repeat(3,1fr)}}</style><div class="br"><section class="br-hero"><div><div class="br-title">💾 Backup & Restore Centre</div><div class="br-sub">Daily private, compressed and checksum-verified database protection.</div></div>@can('backup.create')<button class="br-btn" wire:click="createBackup">Create Backup Now</button>@endcan</section><div class="br-stats">@foreach(['total'=>'Available','failed'=>'Failed','running'=>'Running','size'=>'Total Bytes','latest'=>'Latest Backup','verified'=>'Latest Status'] as $k=>$l)<div class="br-stat"><span>{{